args.sparql:
SELECT ?person ?personLabel WHERE {
  ?person p:P39 ?positionStatement.
  ?positionStatement ps:P39 wd:Q16644626.
  ?person rdfs:label ?personLabel.
  FILTER(LANG(?personLabel) = 'en').
} LIMIT 10

SELECT ?person ?personLabel ?age
WHERE {
  ?person p:P39 ?positionStatement;
          wdt:P569 ?birthDate;
          rdfs:label ?personLabel.
  FILTER(LANG(?personLabel) = 'en').
  ?positionStatement ps:P39 wd:Q431525;
                  pq:P580 ?appointmentDate.
  FILTER (year(?appointmentDate) != 0).
  FILTER (year(?birthDate) != 0).
  BIND( (year(?appointmentDate) - year(?birthDate)) AS ?age)
}
ORDER BY ?age
LIMIT 3

SELECT ?person ?personLabel (YEAR(?appointmentDate) - YEAR(?birthDate) AS ?age)
WHERE {
  ?person wdt:P27 wd:Q30;
          p:P39 ?positionStatement;
          wdt:P569 ?birthDate.
  ?positionStatement ps:P39 wd:Q431525;
                  pq:P580 ?appointmentDate.
  ?person rdfs:label ?personLabel.
  FILTER(LANG(?personLabel) = 'en').
  FILTER(YEAR(?appointmentDate) > 0 && YEAR(?birthDate) > 0).
}
ORDER BY ?age
LIMIT 3
